using System.Collections.Generic;
using System.Linq;
using System.Net;

namespace app_desktop.Services.SteamExclusions;

internal static class SteamExclusionConsentHtmlBuilder
{
	internal static string BuildDocument(IReadOnlyList<string> paths, bool enable)
	{
		string value = string.Join("", paths.Select((string path) => "<li><span class=\"folder-mark\" aria-hidden=\"true\"></span><span>" + WebUtility.HtmlEncode(path) + "</span></li>"));
		return $"<!doctype html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src https://nestg-assets.local; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'\">\n<title>NestG — Ngoại lệ game</title>\n<style>\n:root {{ color-scheme: dark; font-family: 'Segoe UI Variable Text', 'Segoe UI', sans-serif; color: #e8f1fa; background: #0b131d; }}\n* {{ box-sizing: border-box; }}\nhtml, body {{ margin: 0; width: 100%; height: 100%; overflow: hidden; }}\nbutton {{ font: inherit; cursor: pointer; }}\nbutton:focus-visible, [tabindex]:focus-visible {{ outline: 2px solid #72c9fa; outline-offset: 3px; }}\n.window {{ height: 100%; display: grid; grid-template-rows: 64px minmax(0,1fr) 76px; border: 1px solid #30465b; background: radial-gradient(ellipse at top right, #142537 0, transparent 65%), #0b131d; }}\n.titlebar {{ display: flex; align-items: center; justify-content: space-between; padding: 0 18px 0 24px; border-bottom: 1px solid #ffffff09; user-select: none; }}\n.brand {{ display: flex; gap: 10px; align-items: center; font-size: 20px; font-weight: 750; letter-spacing: -.4px; }}\n.brand img {{ width: 28px; height: 34px; object-fit: contain; }}\n.close {{ display: grid; place-items: center; width: 36px; height: 36px; padding: 0; border: 0; border-radius: 8px; color: #a9bfd1; background: transparent; }}\n.close:hover {{ background: #243546; color: white; }}\n.close svg {{ width: 18px; height: 18px; stroke: currentColor; stroke-width: 1.7; }}\nmain {{ min-height: 0; padding: 22px 24px; overflow: auto; scrollbar-gutter: stable; }}\nh1 {{ margin: 0 0 7px; font-size: 26px; line-height: 1.2; letter-spacing: -.6px; font-weight: 650; }}\n.intro {{ margin: 0 0 20px; font-size: 13px; line-height: 1.5; color: #a8bed2; }}\n.folder-heading {{ display: flex; align-items: center; justify-content: space-between; margin-bottom: 9px; font-size: 11px; font-weight: 600; letter-spacing: 1px; color: #a8bed2; }}\n.count {{ border: 1px solid #33495c; border-radius: 20px; padding: 2px 8px; font-size: 11px; letter-spacing: 0; color: #bcd6ea; }}\n.folders {{ margin: 0 0 16px; padding: 0; max-height: 132px; overflow: auto; list-style: none; border: 1px solid #2b4052; border-radius: 10px; background: #132230; }}\n.folders li {{ display: flex; gap: 12px; align-items: flex-start; padding: 15px 16px; font-size: 13px; line-height: 1.6; }}\n.folders li + li {{ border-top: 1px solid #ffffff0c; }}\n.folders li > span:last-child {{ min-width: 0; white-space: pre-wrap; overflow-wrap: anywhere; user-select: text; }}\n.folder-mark {{ flex: 0 0 17px; height: 13px; margin-top: 5px; border: 1.5px solid #7bb9df; border-radius: 2px; position: relative; }}\n.folder-mark::before {{ content: ''; position: absolute; width: 7px; height: 3px; border: 1.5px solid #7bb9df; border-bottom: 0; top: -4px; left: -1.5px; border-radius: 2px 2px 0 0; background: #132230; }}\n.notice {{ display: flex; gap: 11px; border: 1px solid #d3a1532c; background: #b7802710; padding: 13px 15px; border-radius: 10px; }}\n.notice svg {{ flex: 0 0 18px; width: 18px; height: 18px; margin-top: 1px; stroke: #d9b478; fill: none; stroke-width: 1.6; }}\n.notice strong {{ display: block; color: #e1c396; font-size: 12px; font-weight: 600; margin-bottom: 5px; }}\n.notice p {{ margin: 0; color: #c8beaf; font-size: 12px; line-height: 1.65; }}\n.permission {{ display: flex; align-items: flex-start; gap: 9px; margin: 16px 0 0; font-size: 12px; line-height: 1.6; color: #a4b9cc; }}\n.permission svg {{ width: 15px; height: 18px; flex: 0 0 15px; margin-top: 1px; fill: none; stroke: #8cabbe; stroke-width: 1.5; }}\nfooter {{ display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 24px; border-top: 1px solid #2b3b4b; background: #101c28; }}\n.shortcut {{ color: #94aabe; font-size: 11px; }}\n.actions {{ display: flex; gap: 10px; }}\n.actions button {{ min-width: 112px; height: 42px; padding: 0 18px; border-radius: 8px; font-size: 13px; font-weight: 600; }}\n.secondary {{ border: 1px solid #3c5369; background: #1b2c3c; color: #e4edf5; }}\n.secondary:hover {{ background: #263e52; }}\n.primary {{ border: 1px solid #55baf0; background: #55baf0; color: #082338; }}\n.primary:hover {{ background: #78cbf8; }}\nbutton:disabled {{ opacity: .55; cursor: wait; }}\n.error {{ margin: 12px 0 0; font-size: 12px; color: #f5b8a4; }}\n[hidden] {{ display: none !important; }}\n::-webkit-scrollbar {{ width: 6px; height: 6px; }}\n::-webkit-scrollbar-thumb {{ background: #3a5267; border-radius: 8px; }}\n::-webkit-scrollbar-track {{ background: transparent; }}\n@media (max-height: 520px) {{\n    .window {{ grid-template-rows: 52px minmax(0,1fr) 66px; }}\n    main {{ padding: 14px 20px; }}\n    h1 {{ font-size: 23px; }}\n    .intro {{ margin-bottom: 12px; }}\n    .folders {{ max-height: 90px; margin-bottom: 12px; }}\n    .notice {{ padding: 10px 12px; }}\n    .permission {{ margin-top: 12px; }}\n}}\n@media (max-width: 420px) {{\n    .titlebar {{ padding-inline: 16px; }}\n    main {{ padding-inline: 16px; }}\n    footer {{ padding-inline: 16px; }}\n    .shortcut {{ display: none; }}\n    .actions {{ margin-left: auto; }}\n    .actions button {{ min-width: 100px; }}\n}}\n</style>\n</head>\n<body>\n<section class=\"window\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"consent-title\" aria-describedby=\"consent-intro\">\n    <header class=\"titlebar\" data-drag>\n        <div class=\"brand\"><img src=\"https://nestg-assets.local/logo.png\" alt=\"\"><span>NestG</span></div>\n        <button class=\"close\" type=\"button\" data-response=\"no\" aria-label=\"Đóng\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 6 12 12M18 6 6 18\"/></svg></button>\n    </header>\n    <main tabindex=\"0\" aria-label=\"Nội dung xác nhận\">\n        <h1 id=\"consent-title\">{(enable ? "Bật ngoại lệ game" : "Tắt ngoại lệ game")}</h1>\n        <p class=\"intro\" id=\"consent-intro\">{(enable ? "Áp dụng cho các thư mục Steam bên dưới." : "Gỡ các mục được xác nhận do NestG thêm.")}</p>\n        <div class=\"folder-heading\"><span>THƯ MỤC ÁP DỤNG</span><span class=\"count\">{paths.Count} thư mục</span></div>\n        <ul class=\"folders\" tabindex=\"0\" aria-label=\"Danh sách thư mục\">{value}</ul>\n        <aside class=\"notice\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v6m0 3v1\"/></svg>\n            <div><strong>{(enable ? "Lưu ý trước khi tiếp tục" : "Giữ nguyên các ngoại lệ khác")}</strong>\n            <p>{(enable ? "Microsoft Defender sẽ bỏ qua quét các thư mục này, làm giảm bảo vệ. Chỉ đồng ý khi bạn tin cậy các file game." : "Chỉ gỡ các ngoại lệ có lịch sử do NestG thêm. Các mục có sẵn hoặc không xác định được nguồn gốc sẽ được giữ nguyên.")}</p></div>\n        </aside>\n        <p class=\"permission\"><svg viewBox=\"0 0 20 24\" aria-hidden=\"true\"><path d=\"M10 2 2 5v6c0 5 4 8 8 11 4-3 8-6 8-11V5Z\"/><path d=\"m6 12 3 3 5-6\"/></svg><span>Windows sẽ hỏi quyền quản trị. Thay đổi áp dụng cho mọi tài khoản trên máy và được kiểm tra trước khi báo hoàn tất.</span></p>\n        <p class=\"error\" role=\"alert\" hidden></p>\n    </main>\n    <footer><span class=\"shortcut\">Esc để hủy</span><div class=\"actions\">\n        <button type=\"button\" class=\"secondary\" data-response=\"no\" id=\"decline\">Để sau</button>\n        <button type=\"button\" class=\"primary\" data-response=\"yes\">Đồng ý</button>\n    </div></footer>\n</section>\n<script>\n(() => {{\n    let submitted = false;\n    const decline = document.getElementById('decline');\n    function respond(token) {{\n        if (submitted) return;\n        try {{\n            if (!window.chrome?.webview?.postMessage) throw new Error('Bridge unavailable');\n            submitted = true;\n            document.querySelectorAll('button').forEach(button => button.disabled = true);\n            window.chrome.webview.postMessage(token);\n        }} catch {{\n            submitted = false;\n            document.querySelectorAll('button').forEach(button => button.disabled = false);\n            const error = document.querySelector('.error');\n            error.textContent = 'Không gửi được xác nhận. Đóng cửa sổ và thử lại.';\n            error.hidden = false;\n            error.scrollIntoView({{block:'nearest'}});\n            decline.focus();\n        }}\n    }}\n    document.querySelectorAll('[data-response]').forEach(button => button.addEventListener('click', () => respond(button.dataset.response)));\n    document.addEventListener('keydown', event => {{\n        if (event.key === 'Escape') {{ event.preventDefault(); respond('no'); }}\n        if (event.key === 'Enter') {{\n            event.preventDefault();\n            respond(event.target.closest('[data-response]')?.dataset.response || 'no');\n        }}\n        if (event.key === 'Tab') {{\n            const stops = [...document.querySelectorAll('button:not(:disabled), [tabindex=\"0\"]')];\n            const index = stops.indexOf(document.activeElement);\n            if (event.shiftKey && index <= 0) {{ event.preventDefault(); stops.at(-1)?.focus(); }}\n            else if (!event.shiftKey && index === stops.length - 1) {{ event.preventDefault(); stops[0]?.focus(); }}\n        }}\n    }});\n    document.querySelector('[data-drag]').addEventListener('mousedown', event => {{\n        if (event.button === 0 && !event.target.closest('button')) window.chrome?.webview?.postMessage('window:drag');\n    }});\n    decline.focus();\n}})();\n</script>\n</body>\n</html>";
	}
}
